CREATE DATABASE IF NOT EXISTS registro_buses CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE registro_buses;
CREATE TABLE IF NOT EXISTS roles (id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(50) NOT NULL UNIQUE,descripcion VARCHAR(255),estado VARCHAR(20) NOT NULL DEFAULT 'Activo');
CREATE TABLE IF NOT EXISTS personal (id INT AUTO_INCREMENT PRIMARY KEY,dni VARCHAR(20) UNIQUE,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,telefono VARCHAR(30),email VARCHAR(120),direccion VARCHAR(255),cargo VARCHAR(60),fecha_nacimiento DATE,fecha_ingreso DATE,foto_url VARCHAR(500),estado VARCHAR(20) NOT NULL DEFAULT 'Activo',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS usuarios (id INT AUTO_INCREMENT PRIMARY KEY,usuario VARCHAR(60) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,personal_id INT NULL,rol_id INT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(personal_id) REFERENCES personal(id) ON DELETE SET NULL,FOREIGN KEY(rol_id) REFERENCES roles(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS buses (id INT AUTO_INCREMENT PRIMARY KEY,placa VARCHAR(20) NOT NULL UNIQUE,marca VARCHAR(60),modelo VARCHAR(60),anio INT,color VARCHAR(40),combustible VARCHAR(30),tipo_bus VARCHAR(50),capacidad INT,numero_motor VARCHAR(80),numero_chasis VARCHAR(80),propietario_nombres VARCHAR(120),propietario_apellidos VARCHAR(120),estado VARCHAR(20) NOT NULL DEFAULT 'Activo',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS terminales (id INT AUTO_INCREMENT PRIMARY KEY,sede VARCHAR(100) NOT NULL,distrito VARCHAR(100),direccion VARCHAR(255),estado VARCHAR(20) NOT NULL DEFAULT 'Activo',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS series (id INT AUTO_INCREMENT PRIMARY KEY,vendedor_id INT NULL,terminal_id INT NULL,numero_serie VARCHAR(50) NOT NULL UNIQUE,estado VARCHAR(20) NOT NULL DEFAULT 'Activo',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vendedor_id) REFERENCES personal(id) ON DELETE SET NULL,FOREIGN KEY(terminal_id) REFERENCES terminales(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS rutas (id INT AUTO_INCREMENT PRIMARY KEY,inicio VARCHAR(100) NOT NULL,fin VARCHAR(100) NOT NULL,nombre VARCHAR(160),estado VARCHAR(20) NOT NULL DEFAULT 'Activo',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS paradas (id INT AUTO_INCREMENT PRIMARY KEY,ruta_id INT NOT NULL,nombre VARCHAR(120) NOT NULL,orden INT NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'Activo',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ruta_id) REFERENCES rutas(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS asignaciones (id INT AUTO_INCREMENT PRIMARY KEY,bus_id INT NOT NULL,chofer_id INT NOT NULL,copiloto_id INT NULL,fecha_asignacion DATE NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'Activo',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(bus_id) REFERENCES buses(id) ON DELETE RESTRICT,FOREIGN KEY(chofer_id) REFERENCES personal(id) ON DELETE RESTRICT,FOREIGN KEY(copiloto_id) REFERENCES personal(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS encomiendas (id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(50) NOT NULL UNIQUE,remitente_dni VARCHAR(30),remitente_nombres VARCHAR(100),remitente_apellidos VARCHAR(100),remitente_telefono VARCHAR(30),remitente_email VARCHAR(120),remitente_direccion VARCHAR(255),remitente_ubigeo VARCHAR(10),destinatario_dni VARCHAR(30),destinatario_nombres VARCHAR(100),destinatario_apellidos VARCHAR(100),destinatario_telefono VARCHAR(30),destinatario_email VARCHAR(120),destinatario_direccion VARCHAR(255),destinatario_ubigeo VARCHAR(10),fecha_envio DATE,tipo_documento VARCHAR(30),origen VARCHAR(100),destino VARCHAR(100),documento_ruc VARCHAR(30),razon_social VARCHAR(160),estado VARCHAR(30) NOT NULL DEFAULT 'en_transito',total DECIMAL(10,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS boletos (id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(50) NOT NULL UNIQUE,pasajero_dni VARCHAR(30),pasajero_nombres VARCHAR(100),pasajero_apellidos VARCHAR(100),fecha_viaje DATE,ruta_id INT,bus_id INT,asiento VARCHAR(10),piso VARCHAR(30),precio DECIMAL(10,2) NOT NULL DEFAULT 0,estado VARCHAR(30) NOT NULL DEFAULT 'Reservado',serie_id INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(ruta_id) REFERENCES rutas(id) ON DELETE SET NULL,FOREIGN KEY(bus_id) REFERENCES buses(id) ON DELETE SET NULL,FOREIGN KEY(serie_id) REFERENCES series(id) ON DELETE SET NULL);
INSERT IGNORE INTO roles(nombre,descripcion) VALUES ('Administrador','Acceso total al sistema'),('Chofer','Operación de transporte'),('Vendedor','Venta de boletos y encomiendas');
